-- One-time login codes; only salted digests are stored.
CREATE TABLE AuthOtpChallenge (MaChallenge BIGINT AUTO_INCREMENT PRIMARY KEY, MaUser INT NOT NULL, SoDienThoaiE164 VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, CodeHash CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, CodeSalt CHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, ExpiresAt DATETIME(3) NOT NULL, Attempts TINYINT UNSIGNED NOT NULL DEFAULT 0, CreatedAt DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), CONSTRAINT FK_AuthOtp_User FOREIGN KEY(MaUser) REFERENCES UserAccount(MaUser) ON DELETE CASCADE, INDEX IX_AuthOtp_PhoneCreated(SoDienThoaiE164,CreatedAt), INDEX IX_AuthOtp_Expires(ExpiresAt)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;